import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import api from '../api/axios';
import { Container, Form, Table, Button, Alert, Spinner,Row, Col } from 'react-bootstrap';

const Grades = () => {
  const [classes, setClasses] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [selectedClass, setSelectedClass] = useState('');
  const [selectedSubject, setSelectedSubject] = useState('');
  const [month, setMonth] = useState('');
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [editingCell, setEditingCell] = useState(null); // { studentId, scheduleId }
  const [editValue, setEditValue] = useState('');
  const roles = useSelector(state => state.auth.roles || []);
  const isTeacher = roles.includes('Преподаватель');
  const isDirector = roles.includes('Директор');
  const canEdit = isTeacher || isDirector;

  useEffect(() => {
    // Загружаем списки классов и предметов
    const fetchData = async () => {
      try {
        const [classesRes, subjectsRes] = await Promise.all([
          api.get('/director/classes'),
          api.get('/schedule/subjects')
        ]);
        setClasses(classesRes.data);
        setSubjects(subjectsRes.data);
      } catch (err) {
        console.error('Ошибка загрузки списков:', err);
      }
    };
    fetchData();
    // Устанавливаем текущий месяц по умолчанию
    const now = new Date();
    setMonth(now.toISOString().slice(0, 7)); // YYYY-MM
  }, []);

  const fetchGrades = async () => {
    if (!selectedClass || !selectedSubject) {
      setError('Выберите класс и предмет');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const res = await api.get('/grades', {
        params: {
          class_id: selectedClass,
          subject_id: selectedSubject,
          month: month
        }
      });
      setData(res.data);
    } catch (err) {
      setError(err.response?.data?.message || 'Ошибка загрузки данных');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (studentId, scheduleId, currentGrade) => {
    if (!canEdit) return;
    setEditingCell({ studentId, scheduleId });
    setEditValue(currentGrade !== null ? String(currentGrade) : '');
  };

  const saveGrade = async () => {
    const { studentId, scheduleId } = editingCell;
    const grade = parseInt(editValue);
    if (isNaN(grade) || grade < 1 || grade > 5) {
      alert('Оценка должна быть числом от 1 до 5');
      return;
    }
    try {
      await api.post('/grades', { student_id: studentId, schedule_id: scheduleId, grade });
      // Обновляем локальные данные
      const updatedGrades = data.grades.map(g => {
        if (g.student_id === studentId && g.schedule_id === scheduleId) {
          return { ...g, grade };
        }
        return g;
      });
      // Если не было оценки, добавляем
      if (!updatedGrades.some(g => g.student_id === studentId && g.schedule_id === scheduleId)) {
        updatedGrades.push({ student_id: studentId, schedule_id: scheduleId, grade });
      }
      setData({ ...data, grades: updatedGrades });
      setEditingCell(null);
    } catch (err) {
      alert('Ошибка сохранения: ' + (err.response?.data?.message || ''));
    }
  };

  const getGrade = (studentId, scheduleId) => {
    const found = data?.grades.find(g => g.student_id === studentId && g.schedule_id === scheduleId);
    return found ? found.grade : null;
  };

  // Если ничего не выбрано – показываем сообщение
  if (!selectedClass || !selectedSubject) {
    return (
      <Container className="mt-4">
        <h3>Оценки</h3>
        <Alert variant="info">Выберите класс и предмет, чтобы просмотреть оценки</Alert>
        <Form>
          <Form.Group className="mb-3">
            <Form.Label>Класс</Form.Label>
            <Form.Select value={selectedClass} onChange={e => setSelectedClass(e.target.value)}>
              <option value="">Выберите класс</option>
              {classes.map(c => <option key={c.id} value={c.id}>{c.grade}</option>)}
            </Form.Select>
          </Form.Group>
          <Form.Group className="mb-3">
            <Form.Label>Предмет</Form.Label>
            <Form.Select value={selectedSubject} onChange={e => setSelectedSubject(e.target.value)}>
              <option value="">Выберите предмет</option>
              {subjects.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
            </Form.Select>
          </Form.Group>
          <Form.Group className="mb-3">
            <Form.Label>Месяц</Form.Label>
            <Form.Control type="month" value={month} onChange={e => setMonth(e.target.value)} />
          </Form.Group>
          <Button variant="primary" onClick={fetchGrades}>Показать</Button>
        </Form>
      </Container>
    );
  }

  return (
    <Container className="mt-4">
      <h3>Оценки</h3>
      <Row>
      <Form className="mb-3">
        
        <Col>
        <Form.Group className="mb-2">
          <Form.Label>Класс</Form.Label>
          <Form.Select value={selectedClass} onChange={e => setSelectedClass(e.target.value)}>
            <option value="">Выберите класс</option>
            {classes.map(c => <option key={c.id} value={c.id}>{c.grade}</option>)}
          </Form.Select>
        </Form.Group>
        </Col>
        <Col>
        <Form.Group className="mb-2">
          <Form.Label>Предмет</Form.Label>
          <Form.Select value={selectedSubject} onChange={e => setSelectedSubject(e.target.value)}>
            <option value="">Выберите предмет</option>
            {subjects.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
          </Form.Select>
        </Form.Group>
        </Col>
        <Col>
        <Form.Group className="mb-2">
          <Form.Label>Месяц</Form.Label>
          <Form.Control type="month" value={month} onChange={e => setMonth(e.target.value)} />
        </Form.Group>
        <Button variant="primary" onClick={fetchGrades}>Обновить</Button>
        </Col>
        
      </Form>
      </Row>

      {error && <Alert variant="danger">{error}</Alert>}
      {loading && <Spinner animation="border" />}

      {data && (
        <div style={{ overflowX: 'auto' }}>
          <Table bordered striped hover size="sm">
            <thead>
              <tr>
                <th style={{ position: 'sticky', left: 0, background: 'white', zIndex: 1, minWidth: '200px' }}>
                  ФИО
                </th>
                {data.lessons.map(lesson => (
                  <th key={lesson.id} style={{ minWidth: '80px', textAlign: 'center' }}>
                    {new Date(lesson.date).toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit' })}
                    <br />
                    <small>ур.{lesson.lesson_number}</small>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {data.students.map(student => (
                <tr key={student.id}>
                  <td style={{ position: 'sticky', left: 0, background: 'white', zIndex: 1 }}>
                    {student.last_name} {student.first_name} {student.middle_name}
                  </td>
                  {data.lessons.map(lesson => {
                    const grade = getGrade(student.id, lesson.id);
                    const isEditing = editingCell && editingCell.studentId === student.id && editingCell.scheduleId === lesson.id;
                    return (
                      <td
                        key={lesson.id}
                        style={{
                          textAlign: 'center',
                          cursor: canEdit ? 'pointer' : 'default',
                          backgroundColor: isEditing ? '#ffeeba' : 'inherit'
                        }}
                        onClick={() => canEdit && handleEdit(student.id, lesson.id, grade)}
                      >
                        {isEditing ? (
                          <input
                            type="number"
                            min="1"
                            max="5"
                            value={editValue}
                            onChange={e => setEditValue(e.target.value)}
                            onBlur={saveGrade}
                            onKeyDown={e => e.key === 'Enter' && saveGrade()}
                            autoFocus
                            style={{ width: '50px', textAlign: 'center' }}
                          />
                        ) : (
                          grade !== null ? grade : '—'
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </Table>
        </div>
      )}
    </Container>
  );
};

export default Grades;
